private let q4HCVerifyR2Kernel = MLXFast.metalKernel(name: "q4_hcv2_reduce", inputNames: ["part"], outputNames: ["sT", "inj"], source: """

uint t = thread_position_in_grid.x;
constexpr int NB = N / 8 + 1, MP = MT * 8;
if (t >= uint((N + H) * MP)) return;
uint n = t / MP, m = t % MP;
if (n < uint(N)) {
    if (m >= uint(NR)) { sT[(ulong)n * MP + m] = T(0.0f); return; }
    float sum = 0.0f;
    for (int sp = 0; sp < SPLIT; ++sp) sum += part[((ulong)sp * NB * 8 + n) * MP + m];
    float v = float(T(sum)) / float(H);
    sT[(ulong)n * MP + m] = T(v / (1.0f + exp(-v)));
} else if (m < uint(NR)) {
    float sum = 0.0f;
    for (int sp = 0; sp < SPLIT; ++sp) sum += part[((ulong)sp * NB * 8 + n) * MP + m];
    inj[(ulong)m * H + (n - uint(N))] = T(sum);
}
""")
nonisolated(unsafe) private var q4HCVerifyA3Kernels: [Int: MLXFast.MLXFastKernel] = [:]
nonisolated(unsafe) private var q4HCVerifyB3Kernels: [Int: MLXFast.MLXFastKernel] = [:]
/// (mixed (lead..., D), raw inject logits (lead..., H)) -- the combine applies 2*sigmoid(./H), as after q4HCMixInject
func q4HCVerifyFused(normed: MLXArray, down: QuantizedLinear, up: QuantizedLinear, winj: MLXArray, hc H: Int, d D: Int) -> (MLXArray, MLXArray)? {
    let HD = H * D, M = normed.size / HD, RK = down.weight.dim(0), split = q4HCVerifySplit
    let MT = (M + 7) / 8, MTS = MT % 2 == 0 ? MT / 2 : MT, KS = q4HCVerifyKS, SGPT = 4
    guard M >= 17, M <= q4HCVerifyMaxRows, H == 4, down.bits == 8, down.groupSize == 64, up.bits == 8, up.groupSize == 64,
          down.weight.dim(1) * 4 == HD, up.weight.dim(0) == HD, up.weight.dim(1) * 4 == RK, RK % (8 * KS) == 0, D % 8 == 0,
          (KS - 1) * 4 * MTS * 64 * 4 <= 32768, let srcA = q4HCVerifyA3Source[MT], let srcB = q4HCVerifyB3Source[MTS],
          winj.dim(0) == H, winj.dim(1) == HD, winj.dtype == normed.dtype,
          HD % split == 0, (HD / split) % 64 == 0, let db = down.biases, let ub = up.biases else { return nil }
    EngineWitness.hit("hc_verify_fused")
    let kA: MLXFast.MLXFastKernel
    if let k = q4HCVerifyA3Kernels[MT] { kA = k } else {
        kA = MLXFast.metalKernel(name: "q4_hcv3_down_mt\(MT)", inputNames: ["x", "w", "scales", "biases", "winj"], outputNames: ["part"], source: srcA)
        q4HCVerifyA3Kernels[MT] = kA
    }
    let kB: MLXFast.MLXFastKernel
    if let k = q4HCVerifyB3Kernels[MTS] { kB = k } else {
        kB = MLXFast.metalKernel(name: "q4_hcv3_upmix_mts\(MTS)", inputNames: ["sT", "normed", "w", "scales", "biases"], outputNames: ["mixed"], source: srcB)
        q4HCVerifyB3Kernels[MTS] = kB
    }
    let lead = Array(normed.shape.dropLast()), KC = HD / split, NB = RK / 8 + 1
    let x = normed.reshaped(M, HD)
    let T = normed.dtype
    let nsg = NB * split
    let part = kA([x, down.weight, down.scales, db, winj],
                  template: [("T", T), ("MT", MT), ("NR", M), ("N", RK), ("K", HD), ("KC", KC), ("GS", 64), ("H", H), ("SPLIT", split), ("SGPT", SGPT)],
                  grid: (((nsg + SGPT - 1) / SGPT) * SGPT * 32, 1, 1), threadGroup: (SGPT * 32, 1, 1),
                  outputShapes: [[split, NB * 8, MT * 8]], outputDTypes: [.float32])[0]
    let r = q4HCVerifyR2Kernel([part], template: [("T", T), ("MT", MT), ("NR", M), ("N", RK), ("H", H), ("SPLIT", split)],
                               grid: ((RK + H) * MT * 8, 1, 1), threadGroup: (256, 1, 1),
                               outputShapes: [[RK, MT * 8], [M, H]], outputDTypes: [T, T])
    let ntg = (D / 8) * (MT / MTS)
    let mixed = kB([r[0], x, up.weight, up.scales, ub],
                   template: [("T", T), ("MT", MT), ("MTS", MTS), ("NR", M), ("KR", RK), ("D", D), ("H", H), ("GS", 64), ("KS", KS)],
                   grid: (ntg * KS * 32, 1, 1), threadGroup: (KS * 32, 1, 1),
                   outputShapes: [[M, D]], outputDTypes: [T])[0]
    return (mixed.reshaped(lead + [D]), r[1].reshaped(lead + [H]))
}
